const ELEMENT_PROP_KEYS = new Set(["theme","prefix","suffix","label","partLabel","value","parts","stagger","mergeGap","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  prefix: "",
  suffix: "",
  label: "frames per night, every core busy",
  partLabel: "core",
  value: 2097152,
